@Override public synchronized E getPredOf(E point) throws NoSuchElementException {
  Link<E> link;
  try {
    if (point == null) {
      throw new RuntimeException("trying to hash null value.");
    }
    link = map.get(point);
    link = link.getPrevious();
  } catch (NullPointerException e) {
    throw new NoSuchElementException();
  }
  if (link == null) {
    return null;
  } else {
    return link.getItem();
  }
}
